+        display: grid;
+        gap: 18px;
+      }
+
+      .form-field {
+        padding: 22px;
+        border: 1px solid var(--border);
+        border-radius: 22px;
+        background: var(--surface-solid);
+      }
+
+      .question-header {
+        display: flex;
+        flex-direction: column;
+        gap: 6px;
+        margin-bottom: 14px;
+      }
+
+      .question-title {
+        margin: 0;
+        font-size: 1.08rem;
+        line-height: 1.4;
+      }
+
+      .help-text {
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      .choices {
+        display: grid;
+        gap: 10px;
+      }
+
+      .choice {
+        display: flex;
+        align-items: center;
+        gap: 12px;
+        padding: 14px 16px;
+        border: 1px solid var(--border);
+        border-radius: 16px;
+        background: #f8fafc;
+        transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
+        cursor: pointer;
+      }
+
+      .choice:hover {
+        transform: translateY(-1px);
+        border-color: rgba(79, 70, 229, 0.35);
+        background: #eef2ff;
+      }
+
+      .choice input {
+        width: 18px;
+        height: 18px;
+        accent-color: var(--accent);
+        flex: 0 0 auto;
+      }
+
+      .choice span {
+        font-size: 0.98rem;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+        padding-top: 6px;
+      }
+
+      button {
+        appearance: none;
+        border: 0;
+        border-radius: 999px;
+        padding: 14px 22px;
+        font: inherit;
+        font-weight: 700;
+        color: white;
+        background: linear-gradient(135deg, var(--accent), var(--accent-2));
+        box-shadow: 0 12px 30px rgba(79, 70, 229, 0.28);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.03);
+      }
+
+      .status {
+        min-height: 1.4em;
+        margin: 8px 0 0;
+        color: var(--success);
+        font-weight: 600;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100% - 20px, 920px);
+          margin: 10px auto;
+          padding: 20px;
+          border-radius: 20px;
+        }
+
+        .form-field {
+          padding: 18px;
+          border-radius: 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <div id="root"></div>
+
+    <script>
+      const quizData = [
+        {
+          id: "q1",
+          title: "Which languages are commonly used for building web interfaces?",
+          helpText: "Select all that apply.",
+          options: ["JavaScript", "TypeScript", "HTML", "Rust"],
+        },
+        {
+          id: "q2",
+          title: "Which of these are general-purpose programming languages?",
+          options: ["Python", "Ruby", "Bash", "CSS"],
+        },
+        {
+          id: "q3",
+          title: "Which languages are known for strong performance or systems work?",
+          options: ["C", "C++", "Go", "SQL"],
+        },
+      ];
+
+      function Choice({ questionId, option }) {
+        const inputId = `${questionId}-${option.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
