+            <span>${option}</span>
+          </label>
+        `;
+      }
+
+      function QuestionCard({ question }) {
+        return `
+          <div class="form-field">
+            <div class="question-header">
+              <h2 class="question-title">${question.title}</h2>
+              ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
+            </div>
+            <div class="choices">
+              ${question.options.map((option) => Choice({ questionId: question.id, option })).join("")}
+            </div>
+          </div>
+        `;
+      }
+
+      function QuizApp() {
+        return `
+          <main class="page">
+            <section class="hero">
+              <div class="eyebrow">Quiz</div>
+              <h1>Computer Languages</h1>
+              <p class="subtitle">
+                A quick multi-select quiz about languages you might use in web, systems, and general-purpose programming.
+              </p>
+            </section>
+
+            <form id="quiz-form">
+              ${quizData.map((question) => QuestionCard({ question })).join("")}
+
+              <div class="actions">
+                <button type="submit">Submit</button>
+              </div>
+              <p id="status" class="status" aria-live="polite"></p>
+            </form>
+          </main>
+        `;
+      }
+
+      document.getElementById("root").innerHTML = QuizApp();
+
+      document.getElementById("quiz-form").addEventListener("submit", (event) => {
+        event.preventDefault();
+        document.getElementById("status").textContent = "Submitted successfully.";
+      });
+    </script>
+  </body>
+</html>
*** End Patch
