    <style>
      :root {
        --bg: #f5f7fb;
        --surface: rgba(255, 255, 255, 0.86);
        --surface-solid: #ffffff;
        --text: #0f172a;
        --muted: #64748b;
        --border: #dbe4f0;
        --accent: #4f46e5;
        --accent-2: #7c3aed;
        --success: #16a34a;
        --shadow: 0 20px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(79, 70, 229, 0.14), transparent 30%),
          radial-gradient(circle at top right, rgba(124, 58, 237, 0.12), transparent 28%),
          linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
      }

      .page {
        width: min(920px, calc(100% - 32px));
        margin: 40px auto;
        padding: 32px;
        border: 1px solid rgba(255, 255, 255, 0.7);
        border-radius: 28px;
        background: var(--surface);
        backdrop-filter: blur(14px);
        box-shadow: var(--shadow);
      }

      .hero {
        display: flex;
        flex-direction: column;
        gap: 10px;
        margin-bottom: 28px;
      }

      .eyebrow {
        width: fit-content;
        padding: 6px 12px;
        border-radius: 999px;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--accent);
        background: rgba(79, 70, 229, 0.1);
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.25rem);
        line-height: 1.05;
      }

      .subtitle {
        margin: 0;
        max-width: 64ch;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 18px;
      }

      .form-field {
        padding: 22px;
        border: 1px solid var(--border);
        border-radius: 22px;
        background: var(--surface-solid);
      }

      .question-header {
        display: flex;
        flex-direction: column;
        gap: 6px;
        margin-bottom: 14px;
      }

      .question-title {
        margin: 0;
        font-size: 1.08rem;
        line-height: 1.4;
      }

      .help-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choices {
        display: grid;
        gap: 10px;
      }

      .choice {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 14px 16px;
        border: 1px solid var(--border);
        border-radius: 16px;
        background: #f8fafc;
        transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
        cursor: pointer;
      }

      .choice:hover {
        transform: translateY(-1px);
        border-color: rgba(79, 70, 229, 0.35);
        background: #eef2ff;
      }

      .choice input {
        width: 18px;
        height: 18px;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .choice span {
        font-size: 0.98rem;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 6px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
        box-shadow: 0 12px 30px rgba(79, 70, 229, 0.28);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.03);
      }

      .status {
        min-height: 1.4em;
        margin: 8px 0 0;
        color: var(--success);
        font-weight: 600;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 920px);
          margin: 10px auto;
          padding: 20px;
          border-radius: 20px;
        }

        .form-field {
          padding: 18px;
          border-radius: 18px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const quizData = [
        {
          id: "q1",
          title: "Which languages are commonly used for building web interfaces?",
          helpText: "Select all that apply.",
          options: ["JavaScript", "TypeScript", "HTML", "Rust"],
        },
        {
          id: "q2",
          title: "Which of these are general-purpose programming languages?",
          options: ["Python", "Ruby", "Bash", "CSS"],
        },
        {
          id: "q3",
          title: "Which languages are known for strong performance or systems work?",
          options: ["C", "C++", "Go", "SQL"],
        },
      ];

      function Choice({ questionId, option }) {
        const inputId = `${questionId}-${option.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
        return `
          <label class="choice" for="${inputId}">
            <input id="${inputId}" name="${questionId}" type="checkbox" value="${option}" />
            <span>${option}</span>
          </label>
        `;
      }

      function QuestionCard({ question }) {
        return `
          <div class="form-field">
            <div class="question-header">
              <h2 class="question-title">${question.title}</h2>
              ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
            </div>
            <div class="choices">
              ${question.options.map((option) => Choice({ questionId: question.id, option })).join("")}
            </div>
          </div>
        `;
      }

      function QuizApp() {
        return `
          <main class="page">
            <section class="hero">
              <div class="eyebrow">Quiz</div>
              <h1>Computer Languages</h1>
              <p class="subtitle">
                A quick multi-select quiz about languages you might use in web, systems, and general-purpose programming.
              </p>
            </section>

            <form id="quiz-form">
              ${quizData.map((question) => QuestionCard({ question })).join("")}

              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <p id="status" class="status" aria-live="polite"></p>
            </form>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = QuizApp();

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();
        document.getElementById("status").textContent = "Submitted successfully.";
      });
    </script>
  </body>
</html>
